#!/usr/bin/env python3

"""
RoboMaster 哨兵导航与决策系统

第16课：
LaserScan → 障碍物方向

本课目标：

1. 读取 /scan
2. 遍历 ranges[]
3. 计算每个测距点对应的角度
4. 找到最近障碍物
5. 输出最近障碍物的：
       距离
       方向

核心公式：

    angle = angle_min + i * angle_increment

注意：

角度单位是“弧度”。

最终我们会转换成“度”显示。
"""


# =====================================================
# ROS2
# =====================================================

import rclpy

from rclpy.node import Node


# =====================================================
# LaserScan
# =====================================================

from sensor_msgs.msg import LaserScan


# =====================================================
# 数学库
# =====================================================

import math


# =====================================================
# LaserScan 订阅节点
# =====================================================

class LaserDirectionNode(Node):

    """
    订阅 /scan。

    找到最近障碍物。

    输出：

        距离
        角度
    """

    def __init__(self):

        super().__init__(
            "laser_direction_node"
        )


        # =================================================
        # 创建订阅者
        # =================================================

        self.subscription = self.create_subscription(

            LaserScan,

            "/scan",

            self.scan_callback,

            10
        )


        self.get_logger().info(

            "Laser Direction Node Start!"
        )


    # =====================================================
    # LaserScan 回调函数
    # =====================================================

    def scan_callback(self, scan):

        """
        收到一帧 LaserScan 后执行。

        scan.ranges：

            所有方向的距离。
        """


        # =================================================
        # 最近距离
        # =================================================

        min_distance = float("inf")


        # =================================================
        # 最近障碍物对应的角度
        # =================================================

        min_angle = 0.0


        # =================================================
        # 遍历所有雷达数据
        # =================================================

        for i, distance in enumerate(scan.ranges):


            # -------------------------------------------------
            # 排除无效数据
            # -------------------------------------------------

            if not math.isfinite(distance):

                continue


            # -------------------------------------------------
            # 排除超出雷达范围的数据
            # -------------------------------------------------

            if distance < scan.range_min:

                continue


            if distance > scan.range_max:

                continue


            # =================================================
            # 计算当前数据对应的角度
            # =================================================

            angle = (

                scan.angle_min

                +

                i * scan.angle_increment

            )


            # =================================================
            # 判断是不是最近障碍物
            # =================================================

            if distance < min_distance:

                min_distance = distance

                min_angle = angle


        # =================================================
        # 如果没有有效数据
        # =================================================

        if min_distance == float("inf"):

            self.get_logger().warn(

                "没有有效的雷达数据！"
            )

            return


        # =================================================
        # 弧度 → 角度
        # =================================================

        angle_degree = math.degrees(

            min_angle
        )


        # =================================================
        # 输出结果
        # =================================================

        self.get_logger().info(

            f"最近障碍物："

            f"距离 = {min_distance:.2f} m，"

            f"方向 = {angle_degree:.1f}°"
        )


# =====================================================
# main
# =====================================================

def main(args=None):

    # 初始化 ROS2

    rclpy.init(args=args)


    # 创建节点

    node = LaserDirectionNode()


    # 保持运行

    rclpy.spin(node)


    # 销毁节点

    node.destroy_node()


    # 关闭 ROS2

    rclpy.shutdown()


# =====================================================
# 程序入口
# =====================================================

if __name__ == "__main__":

    main()